"use client";

import { useEffect, useId, useRef } from "react";

import type { NavIconName } from "@/lib/data/navigation";
import { prefersReducedMotion, readMs } from "@/lib/motion";
import { cn } from "@/lib/utils";

type NavIconPlay = "hover" | "select";

const playTimers = new WeakMap<Element, number>();

const interactionEvents = ["pointerdown", "keydown", "wheel", "touchstart"] as const;

let userHasInteracted = false;
let listeningForInteraction = false;

function listenForFirstInteraction() {
  if (userHasInteracted || listeningForInteraction) return;
  listeningForInteraction = true;
  const mark = () => {
    userHasInteracted = true;
    for (const type of interactionEvents) window.removeEventListener(type, mark, true);
  };
  for (const type of interactionEvents) window.addEventListener(type, mark, { capture: true, passive: true });
}

function playNavIcon(icon: Element | null, mode: NavIconPlay) {
  if (!icon || prefersReducedMotion() || icon.getClientRects().length === 0) return;
  if (mode === "select" && (!userHasInteracted || icon.getAttribute("data-play") === "hover")) return;

  window.clearTimeout(playTimers.get(icon));
  icon.removeAttribute("data-play");
  icon.getBoundingClientRect();
  icon.setAttribute("data-play", mode);
  playTimers.set(
    icon,
    window.setTimeout(() => icon.removeAttribute("data-play"), readMs("--nav-icon-play-window")),
  );
}

export function playNavIconIn(scope: Element) {
  playNavIcon(scope.querySelector("[data-nav-icon]"), "hover");
}

