const glyphs: Record<NavIconName, { viewBox: string; Glyph: () => React.ReactNode }> = {
  home: { viewBox: "0 0 26 26", Glyph: HomeGlyph },
  torneos: { viewBox: "0 0 26 26", Glyph: TorneosGlyph },
  leaderboard: { viewBox: "0 0 24 24", Glyph: LeaderboardGlyph },
  misiones: { viewBox: "0 0 18 18", Glyph: MisionesGlyph },
  news: { viewBox: "0 0 20 20", Glyph: NewsGlyph },
  juegos: { viewBox: "0 0 24 24", Glyph: JuegosGlyph },
};

export function NavIcon({
  name,
  active,
  className,
}: {
  name: NavIconName;
  active: boolean;
  className?: string;
}) {
  const ref = useRef<SVGSVGElement>(null);
  const wasActive = useRef(active);
  const { viewBox, Glyph } = glyphs[name];

  useEffect(listenForFirstInteraction, []);

  useEffect(() => {
    if (active && !wasActive.current) playNavIcon(ref.current, "select");
    wasActive.current = active;
  }, [active]);

  return (
    <svg
      ref={ref}
      data-nav-icon
      viewBox={viewBox}
      fill="none"
      aria-hidden
      className={cn("navicon block shrink-0 overflow-visible", className)}
    >
      <Glyph />
    </svg>
  );
}
